contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(reverted || afterMinSum == beforeMinSum);
    }

    receive() external payable {}
}

